     "summary": "9月15日，奥克股份(300082.SZ)公告称，公司与大连理工大学联合申报的“环氧衍生聚合物固态电解质材料的研发及中试应用”入选2026年辽宁省科技重大专项计划项目，双方已签署合作研究合同书，共同承担该课题。项目执行期为2026年5月1日至2029年4月30日，公司已收到辽宁省科技厅拨付的专项研发资金500万元，并向大连理工大学支付250万元。（文章来源：每日经济新闻）",
